#include "test.hpp"
#include "mspa/mspa.hpp"
using namespace mspa;
int main(){AgentPsychState s{};s.id={WorldId(1),7};s.last_processed_time=PsychTime(90);s.rng_state.state=42;s.mood={-0.2f,0.8f,PsychTime(80)};Proposition p{};p.predicate=PredicateId(1);p.name_space=NamespaceId(1);p.has_time=true;p.time=PsychTime(60);BeliefState b{};b.id=BeliefId(1);b.proposition=p;b.certainty=0.8f;b.updated_at=PsychTime(70);s.beliefs.push_back(b);s.emotions.push_back({BasicEmotion::Fear,0.9f,PsychTime(50),PsychTime(85)});GoalState g{};g.id=GoalId(1);g.concept_id=ConceptId(1);g.priority=0.8f;g.commitment=0.7f;g.created_at=PsychTime(40);g.updated_at=PsychTime(80);s.goals.push_back(g);MemoryState m{};m.id=MemoryId(1);m.proposition=p;m.importance=0.8f;m.event_time=PsychTime(30);m.last_reactivated_at=PsychTime(75);s.memories.push_back(m);LearnedExpectation le{};le.action=ActionTypeId(1);le.context_tags={"x"};le.outcome_tag="ok";le.attempts=2;le.successes=1;le.confidence=0.5f;le.last_activation=PsychTime(88);s.learned_expectations.push_back(le);ExportedAgent e{s,{TimeDomainId(1),{10,1}},PsychTime(100)};auto bytes=serialize_agent(e);require(bytes&&bytes.value_if()->size()>32,"serialize");auto back=deserialize_agent(*bytes.value_if());require(back,"deserialize");require(back.value_if()->state.id==s.id&&back.value_if()->state.memories.size()==1,"roundtrip");ImportOptions io{};io.destination_id={WorldId(2),9};io.import_time=PsychTime(1000);io.destination_seed_root=999;auto imp=import_agent_state(e,{TimeDomainId(2),{20,1}},io);require(imp,"rebase import");auto&d=imp.value_if()->state;require(d.last_processed_time==PsychTime(980),"last time rebased");require(d.mood.updated_at==PsychTime(960),"mood time rebased");require(d.emotions[0].started_at==PsychTime(900),"emotion time rebased");require(d.goals[0].created_at==PsychTime(880),"goal time rebased");require(d.memories[0].event_time==PsychTime(860),"memory time rebased");require(d.learned_expectations[0].last_activation==PsychTime(976),"learning time rebased");require(d.rng_state.state!=42,"rng rekeyed");std::vector<std::uint8_t>bad={1,2,3};require(!deserialize_agent(bad),"malformed serialization rejected");std::cout<<"persistence ok\n";}
